function simulate(n, k) {
  let inFlight = 0, maxInFlight = 0, done = 0, next = 0;
  const queue = [];
  while (done < n) {
    // backpressure: only admit work while a slot is free
    while (inFlight < k && next < n) {
      inFlight++; next++;
      if (inFlight > maxInFlight) maxInFlight = inFlight;
      queue.push(next);
    }
    // a task finishes, freeing exactly one slot
    queue.shift();
    inFlight--; done++;
  }
  return maxInFlight;
}

const boundedPeak = simulate(7, 3);
if (boundedPeak !== 3) throw new Error('cap broken: peak ' + boundedPeak);
console.log('bounded(k=3) peak in-flight: ' + boundedPeak);

const N = 10000;
const unbounded = simulate(N, N);   // Promise.all(map): all N at once
const pooled = simulate(N, 20);     // p-limit(20): at most 20
if (unbounded !== N) throw new Error('unbounded should be N');
if (pooled !== 20) throw new Error('pool cap broken');
console.log('unbounded peak: ' + unbounded);
console.log('pooled(k=20) peak: ' + pooled);
console.log('cap respected: ' + (pooled <= 20));

